    // 1. Null pointer checks
    if ((momentum_error_nms == NULL) || (field_body_t == NULL) || 
        (command == NULL) || (achievable_torque_nm == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Validate inputs: finiteness and range
    if ((!adcs_is_finite_vec3(momentum_error_nms)) || 
        (!adcs_is_finite_vec3(field_body_t)) || 
        (!isfinite(torque_gain_s_inv)) || (!isfinite(max_dipole_a_m2)) || 
        (torque_gain_s_inv < 0.0) || (max_dipole_a_m2 < 0.0)) {
        command->command->x = 0.0;
        command->command->y = 0.0;
        command->command->z = 0.0;
        command->saturated_axes = 0U;
        achievable_torque_nm->x = 0.0;
        achievable_torque_nm->y = 0.0;
        achievable_torque_nm->z = 0.0;
        return ADCS_E_RANGE;
    }

    // 3. Degenerate magnetic field check
    double b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= 1.0e-24) { // 1e-12 squared
        command->command->x = 0.0;
        command->command->y = 0.0;
        command->command->z = 0.0;
        command->saturated_axes = 0U;
        achievable_torque_nm->x = 0.0;
        achievable_torque_nm->y = 0.0;
        achievable_torque_nm->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    // 4. Desired torque: tau_d = -gain * h_err
    adcs_vec3_t tau_d = adcs_vec3_scale(momentum_error_nms, -torque_gain_s_inv);

    // 5. Minimum norm dipole: m = (B x tau_d) / ||B||^2
    adcs_vec3_t cross = adcs_vec3_cross(field_body_t, &tau_d);
    adcs_vec3_t m = adcs_vec3_scale(&cross, 1.0 / b2);

    // 6. Norm saturation
    double n = adcs_vec3_norm(&m);
    command->saturated_axes = 0U;
    if (n > max_dipole_a_m2) {
        double scale = max_dipole_a_m2 / n;
        m = adcs_vec3_scale(&m, scale);
        command->saturated_axes = 7U;
    }

    // Assign command dipole
    command->command = m;

    // 7. Achievable torque: tau = m x B
    *achievable_torque_nm = adcs_vec3_cross(&m, field_body_t);

    return ADCS_OK;
}

